SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+07:00";

-- ------------------------------------------------------------------------------
-- 1. DATA MASTER PERIODE RPJMN (visirpjmn)
-- Digunakan untuk LEFT JOIN relasi periode tahun di controller (contoh: 2025-2029)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `visirpjmn` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `Visi` text NOT NULL,
  `TahunMulai` int(11) NOT NULL,
  `TahunAkhir` int(11) NOT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ON DUPLICATE KEY UPDATE 
  `Visi` = VALUES(`Visi`), 
  `TahunMulai` = VALUES(`TahunMulai`), 
  `TahunAkhir` = VALUES(`TahunAkhir`);

-- ------------------------------------------------------------------------------
-- 2. DATA MASTER KEMENTERIAN / LEMBAGA PENGAMPU (kementerian)
-- Digunakan untuk mapping nama kementerian pengampu di controller & view
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `kementerian` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `NamaKementerian` varchar(255) NOT NULL,
  `TahunMulai` varchar(4) DEFAULT NULL,
  `TahunAkhir` varchar(4) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;




