-- 13. TABEL LEGACY: SASARAN PRIORITAS NASIONAL (sasaran_prioritas_nasional)
-- ------------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS `sasaran_prioritas_nasional` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
