  PRIMARY KEY (`Id`),
  KEY `_Id` (`_Id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4;



-- ------------------------------------------------------------------------------
-- AKTIFKAN KEMBALI FOREIGN KEY CHECKS
