SET FOREIGN_KEY_CHECKS = 1;

-- ------------------------------------------------------------------------------
-- VERIFIKASI HASIL IMPORT (Menghilangkan pesan 'hasil kosong' di phpMyAdmin)
-- ------------------------------------------------------------------------------
SELECT 
  'UPDATE BERHASIL!' AS `Status_Import`,
  (SELECT COUNT(*) FROM `rkp_ps_prioritas_nasional` WHERE `deleted_at` IS NULL) AS `Total_Prioritas_Nasional`,
  (SELECT COUNT(*) FROM `rkp_ps_pn_sasaran` WHERE `deleted_at` IS NULL) AS `Total_Sasaran_PN`,
  (SELECT COUNT(*) FROM `rkp_ps_pn_indikator` WHERE `deleted_at` IS NULL) AS `Total_Indikator_PN`,
  (SELECT COUNT(*) FROM `rkp_ps_program_prioritas` WHERE `deleted_at` IS NULL) AS `Total_Program_Prioritas`,
  (SELECT COUNT(*) FROM `rkp_ps_kegiatan_prioritas` WHERE `deleted_at` IS NULL) AS `Total_Kegiatan_Prioritas`,
  (SELECT COUNT(*) FROM `rkp_ps_kp_indikator` WHERE `deleted_at` IS NULL) AS `Total_Indikator_KP`;

