REPLACE INTO `rkp_ps_prioritas_nasional` (`Id`, `_IdVisi`, `PrioritasNasional`, `created_at`, `updated_at`, `deleted_at`) VALUES
  ('1', '1', 'Memperkokoh Ideologi Pancasila, Demokrasi, dan Hak Asasi Manusia', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('2', '1', 'Memantapkan Sistem Pertahanan Keamanan Negara dan Mendorong Kemandirian Bangsa melalui Swasembada Pangan, Energi, Air, Ekonomi Syariah, Ekonomi Digital, Ekonomi Hijau, dan Ekonomi Biru', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('3', '1', 'Melanjutkan Pengembangan Infrastruktur dan Meningkatkan Lapangan Kerja yang Berkualitas, Mendorong Kewirausahaan, Mengembangkan Industri Kreatif serta Mengembangkan Agromaritim Industri di Sentra Produksi melalui Peran Aktif Koperasi', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('4', '1', 'Memperkuat Pembangunan Sumber Daya Manusia (SDM), Sains, Teknologi, Pendidikan, Kesehatan, Prestasi Olahraga, Kesetaraan Gender, Serta Penguatan Peran Perempuan, Pemuda (Generasi Milenial dan Generasi 2), dan Penyandang Disabilitas', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('5', '1', 'Melanjutkan Hilirisasi dan Mengembangkan Industri Berbasis Sumber Daya Alam untuk Meningkatkan Nilai Tambah di Dalam Negeri', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('6', '1', 'Membangun dari Desa dan dari Bawah untuk Pertumbuhan Ekonomi, Pemerataan Ekonomi, dan Pemberantasan Kemiskinan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('7', '1', 'Memperkuat Reformasi Politik, Hukum, dan Birokrasi, serta Memperkuat Pencegahan dan Pemberantasan Korupsi, Narkoba, Judi, dan Penyelundupan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('8', '1', 'Memperkuat Penyelarasan Kehidupan yang Harmonis dengan Lingkungan Alam dan Budaya, serta Peningkatan Toleransi Antarumat Beragama untuk Mencapai Masyarakat yang Adil dan Makmur', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL);
REPLACE INTO `rkp_ps_pn_sasaran` (`Id`, `_IdPN`, `Sasaran`, `created_at`, `updated_at`, `deleted_at`) VALUES
  ('1', '1', 'Terwujudnya kehidupan bermasyarakat, berbangsa, dan bernegara yang berlandaskan Pancasila, demokrasi, dan hak asasi manusia', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('2', '2', 'Terjaganya kedaulatan negara dan penguatan stabilitas keamanan nasional sebagai fondasi pelaksanaan pembangunan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('3', '2', 'Meningkatkan kemandirian bangsa dalam memenuhi kebutuhan pangan yang berkualitas secara berkelanjutan dengan pendekatan nexus pangan, energi. dan air (FEW Nexus)', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('4', '2', 'Meningkatkan kemandirian bangsa dalam memenuhi kebutuhan energi secara berkelanjutan. dengan pendekatan nexus pangan, energi, dan air (FEW Nexus', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('5', '2', 'Meningkatkan kemandirian bangsa dalam memenuhi kebutuhan air secara berkelanjutan dengan pendekatan nexus pangan, energi, dan air (FEW Nexus)', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('6', '2', 'Terwujudnya perekonomian nasional yang inklusif dan berkelanjutan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('7', '2', 'Terwujudnya transformasi ekonomi hijau', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('8', '3', 'Terwujudnya pengembangan infrastruktur yang berkelanjutan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('9', '3', 'Meningkatnya total aset sektor keuangan terhadap PDB', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('10', '3', 'Meningkatnya lapangan kerja yang berkualitas', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('11', '3', 'Meningkatnya nilai tambah pariwisata', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('12', '3', 'Meningkatnya proporsi PDB ekonomi kreatif', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('13', '4', 'Terwujudnya pendidikan berkualitas yang merata', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('14', '4', 'Terwujudnya kesehatan untuk semua', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('15', '4', 'Terwujudnya keluarga berkualitas, kesetaraan gender, dan masyarakat inklusif', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('16', '4', 'Menguatnya iptek, inovasi, dan produktivitas tenaga kerja', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('17', '4', 'Meningkatnya prestasi olahraga Indonesia di tingkat dunia dan budaya berolahraga di masyarakat', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('18', '5', 'Terwujudnya peningkatan nilai tambah, produktivitas dan daya saing industri pengolahan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('19', '5', 'Terwujudnya peningkatan integrasi ekonomi domestik dan global', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('20', '6', 'Mempercepat pengurangan kemiskinan dan peningkatan pemerataan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('21', '6', 'Meningkatnya akses hunian layak, terjangkau, dan berkelanjutan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('22', '6', 'Mewujudkan pembangunan kemandirian perdesaan dari bawah sebagai sumber pertumbuhan ekonomi yang berkelanjutan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('23', '6', 'Perkotaan sebagai pusat pertumbuhan ekonomi', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('24', '7', 'Terwujudnya supremasi hukum yang transparan, adil, dan tidak memihak serta sistem politik yang fungsional', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('25', '7', 'Terwujudnya birokrasi pemerintahan yang adaptif dan melayani', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('26', '7', 'Terwujudnya masyarakat yang bebas dari penyalahgunaan narkoba', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('27', '7', 'Terwujudnya tata kelola BUMN yang baik untuk meningkatkan kontribusi BUMN sebagai agen pembangunan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('28', '7', 'Tercapainya peningkatan pendapatan negara yang optimal dengan tetap menjaga iklim investasi, didukung upaya mewujudkan reformasi fiskal secara komprehensif melalui optimalisasi belanja negara serta perluasan sumber dan pengembangan inovasi pembiayaan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('29', '7', 'Tercapainya tingkat inflasi yang rendah dan stabil untuk mendukung stabilitas serta pertumbuhan ekonomi yang inklusif dan berkelanjutan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('30', '8', 'Terwujudnya kehidupan beragama yang maslahat dan berkebudayaan maju', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('31', '8', 'Terwujudnya resiliensi terhadap bencana dan perubahan iklim', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL);
