  ('51', '35', 'Terwujudnya. kualitas pengajaran dan pembelajaran yang efektif', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('52', '36', 'Terwujudnya layanan pendidikan pesantren dan pendidikan keagamaan yang berkualitas', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('53', '37', 'Terwujudnya peningkatan kompetensi, profesionalisme, dan pemerataan distribusi pendidik dan tenaga kependidikan untuk mewujudkan pelayanan pendidikan yang berkualitas dan inklusif', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('54', '38', 'Terselenggaranya sistem tata kelola pendidikan yang efektif untuk meningkatkan kualitas pembelajaran dan pengajaran, serta reputasi kelembagaan pendidikan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('55', '39', 'Meningkatnya penyelenggaraan pendidikan tinggi berkualitas yang merata dan berkembangnya STEAM di pendidikan tinggi', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('56', '40', 'Terwujudnya tenaga kerja yang produktif dan berdaya saing yang relevan dengan kebutuhan industri', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('57', '41', 'Meningkatnya proporsi anggaran iptek dan inovasi terhadap PDB untuk mendukung pembangunan nasional', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('58', '42', '-Terwujudnya talenta riset inovasi, seni budaya, dan olahraga yang memperoleh rekognisi di tingkat nasional dan internasional', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('59', '43', 'Terwujudnya masyarakat literat untuk meningkatkan kreativitas, inovasi, dan daya cipta', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('60', '44', 'Meningkatnya kesehatan dan gizi masyarakat berbasis siklus hidup melalui penguatan edukasi, peningkatan kualitas layanan kesehatan dan intervensi perbaikan gizi sesuai standar, serta mencegah kematian dini dan meningkatkan harapan hidup sehat', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('61', '45', 'Terlaksananya pemberian makan bergizi gratis bagi anak balita, ibu hamil, ibu menyusui, dan anak sekolah sekolah untuk mencapai pemenuhan gizi', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('62', '46', 'Meningkatnya pengendalian penyakit melalui upaya pencegahan, penemuan kasus, dan penuntasan pengobatan', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
  ('63', '47', 'Meningkatnya kapasitas ketahanan kesehatan untuk melindungi penduduk dari ancaman kedaruratan kesehatan, termasuk penyakit emerging dan re-emerging, dengan meningkatkan kemampuan dalam mencegah, mendeteksi, dan merespons secara efektif dan cepat', '2026-08-10 15:39:17', '2026-08-10 15:39:17', NULL),
